                // settings/pose edit cannot race the run. The close is
                // deliberate — the dirty-close guard must not fire.
                settingsDialog.discardConfirmed = true
                poseDialog.discardConfirmed = true
                settingsDialog.close()
                poseDialog.close()
                optimizerBridge.run()
            }
        }
    }
